// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetHealth Liveness and database readiness
	// (GET /healthz)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// ListApprovals Every reviewer approval (admin)
	// (GET /v1/approvals)
	ListApprovals(w http.ResponseWriter, r *http.Request)
	// ApproveReviewer Approve a user to review a language, or change their level (admin)
	// (PUT /v1/approvals)
	ApproveReviewer(w http.ResponseWriter, r *http.Request)
	// RevokeApproval Remove a reviewer approval (admin)
	// (DELETE /v1/approvals/{user_id}/{language})
	RevokeApproval(w http.ResponseWriter, r *http.Request, userId string, language LanguageCode)
	// GetConcept A meaning across all languages
	// (GET /v1/concepts/{id})
	GetConcept(w http.ResponseWriter, r *http.Request, id Id, params GetConceptParams)
	// CreateContribution Propose a word (contributors)
	// (POST /v1/contributions)
	CreateContribution(w http.ResponseWriter, r *http.Request)
	// ListCredits The volunteers behind a language's data
	// (GET /v1/credits)
	ListCredits(w http.ResponseWriter, r *http.Request, params ListCreditsParams)
	// DetectLanguage Detect the language of a text
	// (POST /v1/detect)
	DetectLanguage(w http.ResponseWriter, r *http.Request)
	// ListDisputes Disagreements waiting for a senior reviewer (senior reviewers)
	// (GET /v1/disputes)
	ListDisputes(w http.ResponseWriter, r *http.Request)
	// ResolveDispute Settle a dispute (senior reviewers)
	// (POST /v1/disputes/{sense_id}/resolution)
	ResolveDispute(w http.ResponseWriter, r *http.Request, senseId openapi_types.UUID)
	// SearchEntries Search a language's dictionary entries
	// (GET /v1/entries/search)
	SearchEntries(w http.ResponseWriter, r *http.Request, params SearchEntriesParams)
	// GetEntry A full dictionary entry
	// (GET /v1/entries/{id})
	GetEntry(w http.ResponseWriter, r *http.Request, id Id, params GetEntryParams)
	// ListKeys Your API keys
	// (GET /v1/keys)
	ListKeys(w http.ResponseWriter, r *http.Request)
	// CreateKey Create an API key
	// (POST /v1/keys)
	CreateKey(w http.ResponseWriter, r *http.Request)
	// RevokeKey Revoke an API key
	// (DELETE /v1/keys/{id})
	RevokeKey(w http.ResponseWriter, r *http.Request, id Id)
	// ListLanguages Supported and planned languages
	// (GET /v1/languages)
	ListLanguages(w http.ResponseWriter, r *http.Request)
	// Lookup Translate a word between English and Zambian languages
	// (GET /v1/lookup)
	Lookup(w http.ResponseWriter, r *http.Request, params LookupParams)
	// GetMe The signed-in user, with role and review approvals
	// (GET /v1/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// SetCredit Choose whether to be credited by name
	// (PUT /v1/me/credit)
	SetCredit(w http.ResponseWriter, r *http.Request)
	// GetPhrasePack A curated phrase pack in one language
	// (GET /v1/phrases)
	GetPhrasePack(w http.ResponseWriter, r *http.Request, params GetPhrasePackParams)
	// GetProviderQuality Acceptance and correction rates per AI provider and language (admin)
	// (GET /v1/provider-quality)
	GetProviderQuality(w http.ResponseWriter, r *http.Request)
	// ListReports Open reports in a language (reviewers)
	// (GET /v1/reports)
	ListReports(w http.ResponseWriter, r *http.Request, params ListReportsParams)
	// CreateReport Report a wrong meaning
	// (POST /v1/reports)
	CreateReport(w http.ResponseWriter, r *http.Request)
	// DecideReport Confirm or dismiss a report (reviewers)
	// (POST /v1/reports/{id}/decision)
	DecideReport(w http.ResponseWriter, r *http.Request, id Id)
	// GetNextReview The next concept to review (reviewers)
	// (GET /v1/review/next)
	GetNextReview(w http.ResponseWriter, r *http.Request, params GetNextReviewParams)
	// ListReviewers Reviewers of a language with their agreement rates (senior reviewers)
	// (GET /v1/reviewers)
	ListReviewers(w http.ResponseWriter, r *http.Request, params ListReviewersParams)
	// MarkRetrained Record that a reviewer was retrained (senior reviewers)
	// (POST /v1/reviewers/{user_id}/retraining)
	MarkRetrained(w http.ResponseWriter, r *http.Request, userId string)
	// DeleteReviews Undo your own decision (reviewers)
	// (DELETE /v1/reviews)
	DeleteReviews(w http.ResponseWriter, r *http.Request, params DeleteReviewsParams)
	// CreateReviews Record review decisions (reviewers)
	// (POST /v1/reviews)
	CreateReviews(w http.ResponseWriter, r *http.Request)
	// ListSources The source register
	// (GET /v1/sources)
	ListSources(w http.ResponseWriter, r *http.Request)
	// CreateSource Add a source to the register (admin)
	// (POST /v1/sources)
	CreateSource(w http.ResponseWriter, r *http.Request)
	// DeleteSource Remove a source no item cites yet (admin)
	// (DELETE /v1/sources/{id})
	DeleteSource(w http.ResponseWriter, r *http.Request, id Id)
	// GetSource One source
	// (GET /v1/sources/{id})
	GetSource(w http.ResponseWriter, r *http.Request, id Id)
	// UpdateSource Replace a source's details (admin)
	// (PUT /v1/sources/{id})
	UpdateSource(w http.ResponseWriter, r *http.Request, id Id)
	// DownloadPermission Download the permission document (admin)
	// (GET /v1/sources/{id}/permission)
	DownloadPermission(w http.ResponseWriter, r *http.Request, id Id)
	// UploadPermission Upload the signed permission document (admin)
	// (PUT /v1/sources/{id}/permission)
	UploadPermission(w http.ResponseWriter, r *http.Request, id Id)
	// Translate Translate a short text between English and a Zambian language
	// (POST /v1/translate)
	Translate(w http.ResponseWriter, r *http.Request)
}

